class GenericObservers(GenericBts):
    """Observer keywords for eNB and gNB"""
    def ping_callback(self, ping):
        ping.cancel()

    @load_moler_configuration_from_tl()
    def _ping_bts(self, bts_id, event_name, bts_ip, timeout, du_id=0):
        """
        ping bts and wait for response
        :param bts_id: bts id
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param event_name: event waiting for response or rejected packets after ping command
        :param bts_ip: ip address of bts to execute command
        :param timeout: timeout for execute command
        """
        timeout = time_to_seconds(time=timeout)
        sys_device = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id), establish_connection=False)
        sys_device.goto_state("PROXY_PC")
        event = sys_device.get_event(
            event_name=event_name,
            event_params={"till_occurs_times": 1}
        )
        ping = sys_device.get_cmd(cmd_name="ping", cmd_params={
            'destination': bts_ip
        })
        event.add_event_occurred_callback(
            callback=self.ping_callback,
            callback_params={'ping': ping}
        )
        event.start()
        ping.start(timeout=timeout - 20)
        event.await_done(timeout=timeout)
        return

    def verify_host_response(self, bts_id=0, bts_ip="192.168.255.129", timeout=120, du_id=0):
        """
        Using function _ping_bts, wait for host response
        :param bts_id: bts id
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bts_ip: bts ip
        :param timeout: timeout for execute command
        :return:
        """
        self._ping_bts(bts_id, "ping_response", bts_ip, timeout, du_id)

    def verify_host_no_response(self, bts_id=0, bts_ip="192.168.255.129", timeout=120, du_id=0):
        """
        Using function _ping_bts, wait for host  no response
        :param bts_id: bts id
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bts_ip: bts ip
        :param timeout: timeout for execute command
        :return:
        """
        self._ping_bts(bts_id, "ping_no_response", bts_ip, timeout, du_id)

    observers = {}


class EnbObservers(GenericObservers):
    """Class contains Observer keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """

        super(EnbObservers, self).__init__(bts_type=EnbObservers.bts_type)


class DropX2LinkObserver(GenericObservers):
    def __init__(self, bts_type='GNB'):
        """
        Constructor of DropX2LinkObserver class.
        """
        super(DropX2LinkObserver, self).__init__(bts_type=bts_type)

    @load_moler_configuration_from_tl()
    @convert_id_to_int
    def start_drop_x2_link_observer(self, gnb_id=0, timeout=None, du_id=0):
        """
        Start drop X2 link observer on passed gNB and collect snapshot when event occurred.
        :param gnb_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for running observer
        :return: syslog_event
        """
        _re_drop_x2_link = 'report Fault x2LinkNotAvailableAl'
        device_name = self.syslog_alias.format(gnb_id, du_id)
        if 'drop_x2_link' not in self.observers:
            self.observers['drop_x2_link'] = {}

        MolerTest.info("Start drop X2 link observer on device {}".format(device_name))
        sys_device = DeviceFactory.get_device(name=device_name)

        syslog_event = sys_device.get_event(
            event_name="wait4",
            event_params={"detect_patterns": [_re_drop_x2_link],
                          "till_occurs_times": -1, "match": 'all'}
        )

        self.observers['drop_x2_link'][device_name] = syslog_event

        syslog_event.add_event_occurred_callback(
            callback=self._drop_x2_link_callback,
            callback_params={'gnb_id': gnb_id}
        )

        syslog_event.start(timeout=timeout)

        return syslog_event

    def _drop_x2_link_callback(self, gnb_id=0, du_id=0):
        log_info_to_console("\t{} Detected x2LinkNotAvailable in SYSYLOG".format(get_timestamp()))
        log_info_to_console("\t{} Start collecting snapshot via REST API".format(get_timestamp()))

        log_dir = get_builtin_value(param_name="OUTPUT DIR")
        GnbLog().collect_snapshot(gnb_id=gnb_id, log_dir=log_dir, du_id=du_id)

        log_info_to_console("\t{} Collecting snapshot finished".format(get_timestamp()))

    @convert_id_to_int
    def stop_drop_x2_link_observer(self, gnb_id=0, du_id=0):
        """
        Stop drop X2 link observer on passed gNB.
        :param gnb_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """

        device_name = self.syslog_alias.format(gnb_id, du_id)
        try:
            syslog_event = self.observers['drop_x2_link'][device_name]
            syslog_event.cancel()
        except KeyError:
            raise Exception("Please first run 'start_drop_x2_link_observer' for gnb_id={}".format(gnb_id))


class SiteResetObserver(GenericObservers):
    def __init__(self, bts_type='GNB'):
        """
        Constructor of SiteResetObserver class.
        """
        super(SiteResetObserver, self).__init__(bts_type=bts_type)
        self.wasSiteReset = False

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions()
    def start_monitoring_gnb_online_status(self, bts_id=0, du_id=0, callback=None, callback_params=None):
        """
        Start executing recovery action site reset observer on passed bts.
        Use verify_site_reset_not_occurred() to verify if site reset occurred.

        :param bts_id: bts id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param callback: Optional. Function to call, when event occurred.
        :param callback_params: Optional. Parameters to callback.

        """
        syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
        syslog.goto_state('SYSLOG', keep_state=False)

        gnb_recovery = syslog.get_event(event_name="executing_recovery_action_site_reset", event_params={})

        if not callback:
            callback = self._fail_test
            callback_params = {
                'msg': 'executing_recovery_action_site_reset',
            }

        gnb_recovery.add_event_occurred_callback(
            callback=callback,
            callback_params=callback_params,
        )
        gnb_recovery.start()

    @MolerTest.raise_background_exceptions()
    def _fail_test(self, msg):
        self.wasSiteReset = True
        MolerTest.error(raise_exception=True, msg=msg)

    def verify_site_reset_not_occurred(self):
        """
        Verify if site reset occurred.
        start_monitoring_gnb_online_status() function should be called firstly.
        :raises: UnexpectedBtsResetOccurred
        """
        if self.wasSiteReset:
            self.wasSiteReset = False
            raise UnexpectedBtsResetOccurred()


class NrCellAttachObserver(GenericObservers):
    def __init__(self, bts_type='GNB'):
        """
        Constructor of NrCellAttachObserver class.
        """
        super(NrCellAttachObserver, self).__init__(bts_type=bts_type)
        self.attachToNRcell = False

    @load_moler_configuration_from_tl()
    def start_nrcell_attach_observer(self, target_cell, gnb_id=0, timeout=30.0, du_id=0):
        """
        Start handover observer on passed gNB
        :param target_cell: nrcellid of target cell for attach procedure
        :param gnb_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for running observer
        """
        _re_nr_attach = "UserSetupReq_t .* nrCellIdentity = {}, ueAddCause = SGNBADDITION".format(target_cell)
        device_name = self.syslog_alias.format(gnb_id, du_id)
        if 'nrcell_attach' not in self.observers:
            self.observers['nrcell_attach'] = {}

        MolerTest.info("Start nrcell attach observer on device {}".format(device_name))
        sys_device = DeviceFactory.get_device(name=device_name)

        syslog_nrcell_attach = sys_device.get_event(
            event_name="wait4",
            event_params={"detect_patterns": [_re_nr_attach],
                          "match": 'all',
                          "till_occurs_times": 1}
        )

        self.observers['nrcell_attach'][device_name] = syslog_nrcell_attach

        syslog_nrcell_attach.add_event_occurred_callback(
            callback=self._nrcell_attach_callback,
            callback_params={'target_cell': target_cell}
        )

        syslog_nrcell_attach.start(timeout=float(timeout))

    def _nrcell_attach_callback(self, target_cell):
        log_info_to_console("\t{} Attach to NR cell_id:{}".format(get_timestamp(), target_cell))
        self.attachToNRcell = True

    def verify_nrcell_attach(self):
        if self.observers.get('nrcell_attach') is None:
            raise Exception("Please first run 'start_nrcell_attach_observer' ")
        if self.attachToNRcell:
            self.attachToNRcell = False
        else:
            self.attachToNRcell = False
            raise AttachToNRCellFailed()


class HandoverObserver(GenericObservers):
    def __init__(self, bts_type='GNB'):
        """
        Constructor of HandoverObserver class.
        """
        super(HandoverObserver, self).__init__(bts_type=bts_type)
        self.handoverTriggered = False
        self.handoverCompleted = False

    @load_moler_configuration_from_tl()
    def start_handover_observer(self, gnb_id=0, timeout=30.0, du_id=0, target_cell=0, source_cell=0):
        """
        Start handover observer on passed gNB
        :param gnb_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for running observer
        :param source_cell: id of source cell for handover procedure
        :param target_cell: id of target cell for handover procedure
        """
        _re_handover = "Handover triggered from cellId:{} to cellId:{}".format(source_cell, target_cell)
        _re_handover_success = "Update UE context after .* handover for gnbDuUeF1APId"
        device_name = self.syslog_alias.format(gnb_id, du_id)
        if 'handover_trigger' not in self.observers:
            self.observers['handover_trigger'] = {}
        if 'handover_complete' not in self.observers:
            self.observers['handover_complete'] = {}

        MolerTest.info("Start handover observers on device {}".format(device_name))
        sys_device = DeviceFactory.get_device(name=device_name)

        syslog_ho_trigger = sys_device.get_event(
            event_name="wait4",
            event_params={"detect_patterns": [_re_handover],
                          "match": 'all',
                          "till_occurs_times": 1}
        )
        syslog_ho_complete = sys_device.get_event(
            event_name="wait4",
            event_params={"detect_patterns": [_re_handover_success],
                          "match": 'all',
                          "till_occurs_times": 1}
        )

        self.observers['handover_trigger'][device_name] = syslog_ho_trigger
        self.observers['handover_complete'][device_name] = syslog_ho_complete

        syslog_ho_complete.add_event_occurred_callback(
            callback=self._ho_complete_callback,
            callback_params={'target_cell': target_cell,
                             'source_cell': source_cell}
        )
        syslog_ho_trigger.add_event_occurred_callback(
            callback=self._ho_trigger_callback,
            callback_params={'target_cell': target_cell,
                             'source_cell': source_cell}
        )

        syslog_ho_trigger.start(timeout=float(timeout))
        syslog_ho_complete.start(timeout=float(timeout))

    def _ho_complete_callback(self, target_cell, source_cell):
        log_info_to_console("\t{} Detected HO trigger from cell_id:{} to cell_id:{}"
                            .format(get_timestamp(), source_cell, target_cell))
        self.handoverTriggered = True

    def _ho_trigger_callback(self, target_cell, source_cell):
        log_info_to_console("\t{} Handover from cell_id:{} to cell_id:{} completed"
                            .format(get_timestamp(), source_cell, target_cell))
        self.handoverCompleted = True

    @load_moler_configuration_from_tl()
    def verify_handover_completed(self):
        if self.observers.get('handover_complete') is None:
            raise Exception("Please first run 'start_handover_observer' ")
        if self.handoverTriggered and self.handoverCompleted:
            self.handoverCompleted = False
            self.handoverTriggered = False
        else:
            self.handoverCompleted = False
            self.handoverTriggered = False
            raise ExpectedHandoverProcedureFailed()


class GnbObservers(DropX2LinkObserver, SiteResetObserver, NrCellAttachObserver, HandoverObserver):
    """Class is interface for all Observer classes for gNB"""
    bts_type = 'GNB'

    def __init__(self):
        super(GnbObservers, self).__init__(bts_type=GnbObservers.bts_type)
